import * as THREE from 'three';
import * as CANNON from 'cannon-es';
import { Team, BikeState } from '../../../shared/index.js';

export class Player {
  public mesh: THREE.Group;
  public body: CANNON.Body;
  public nameLabel: THREE.Sprite;

  private scene: THREE.Scene;
  private world: CANNON.World;
  private team: Team;
  private type: 'player' | 'ai' | 'remote';
  private teamColor: number;
  private shortsColor: number;

  private torso: THREE.Group;
  private headGroup: THREE.Group;
  private leftArm: THREE.Group;
  private rightArm: THREE.Group;
  private leftLeg: THREE.Group;
  private rightLeg: THREE.Group;

  private animPhase = 0;
  private playerName = '';
  private playerNumber = '';

  // Celebration state
  private isCelebrating = false;
  private celebrateTimer = 0;
  private celebrateDuration = 1.5;
  private armRaiseTarget = -1.8;
  private speechBubble: THREE.Sprite | null = null;
  private speechBubbleTimer = 0;

  constructor(
    scene: THREE.Scene, world: CANNON.World,
    team: Team, type: 'player' | 'ai' | 'remote',
    playerName = '', playerNumber = ''
  ) {
    this.scene = scene;
    this.world = world;
    this.team = team;
    this.type = type;
    this.playerName = playerName || (type === 'ai' ? 'AI' : 'Player');
    this.playerNumber = playerNumber || String(Math.floor(Math.random() * 99) + 1);

    this.teamColor = team === Team.Blue ? 0x00e5ff : 0xef4444;
    this.shortsColor = team === Team.Blue ? 0x0055aa : 0x8b0000;

    this.mesh = new THREE.Group();

    this.torso = this.createBody();
    this.headGroup = this.createHead();
    this.leftArm = this.createArm();
    this.rightArm = this.createArm();
    this.leftLeg = this.createLeg();
    this.rightLeg = this.createLeg();

    this.mesh.add(this.torso);
    this.mesh.add(this.headGroup);
    this.mesh.add(this.leftArm);
    this.mesh.add(this.rightArm);
    this.mesh.add(this.leftLeg);
    this.mesh.add(this.rightLeg);

    this.torso.position.y = 0.05;
    this.headGroup.position.set(0, 0.95, 0);
    this.leftArm.position.set(-0.35, 0.55, 0);
    this.rightArm.position.set(0.35, 0.55, 0);
    this.leftLeg.position.set(-0.15, -0.2, 0);
    this.rightLeg.position.set(0.15, -0.2, 0);

    this.nameLabel = this.createNameLabel();
    this.scene.add(this.mesh);

    this.body = new CANNON.Body({
      mass: 75,
      shape: new CANNON.Cylinder(0.3, 0.3, 1.6, 8),
      material: new CANNON.Material('player'),
    });
    this.body.position.set(0, 0.8, 0);
    this.world.addBody(this.body);
  }

  celebrate() {
    this.isCelebrating = true;
    this.celebrateTimer = 0;
    this.body.velocity.y = 5;

    this.createSpeechBubble();
  }

  private createSpeechBubble() {
    if (this.speechBubble) {
      this.scene.remove(this.speechBubble);
    }

    const canvas = document.createElement('canvas');
    canvas.width = 128;
    canvas.height = 80;
    const ctx = canvas.getContext('2d')!;

    ctx.fillStyle = 'rgba(0,0,0,0.85)';
    const rx = 40, ry = 30;
    ctx.beginPath();
    ctx.roundRect(64 - rx, 10, rx * 2, ry * 2, 12);
    ctx.fill();

    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 32px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('GOAL!', 64, 45);

    const tex = new THREE.CanvasTexture(canvas);
    const mat = new THREE.SpriteMaterial({
      map: tex, transparent: true, depthTest: false, sizeAttenuation: true,
    });
    const sprite = new THREE.Sprite(mat);
    sprite.scale.set(1.2, 0.75, 1);
    sprite.position.set(0, 1.1, 0);
    sprite.renderOrder = 1000;
    this.mesh.add(sprite);
    this.speechBubble = sprite;
    this.speechBubbleTimer = 0;
  }

  private updateCelebration(dt: number) {
    if (!this.isCelebrating) return;

    this.celebrateTimer += dt;
    const progress = Math.min(1, this.celebrateTimer / this.celebrateDuration);

    const armAngle = this.armRaiseTarget * Math.min(1, progress * 3);
    this.leftArm.rotation.x = armAngle;
    this.rightArm.rotation.x = armAngle;

    if (progress >= 1) {
      this.isCelebrating = false;
    }

    if (this.speechBubble) {
      this.speechBubbleTimer += dt;
      const floatY = this.speechBubbleTimer * 0.3;
      this.speechBubble.position.y = 1.1 + floatY;
      const bubbleProgress = Math.min(1, this.speechBubbleTimer / 2);
      this.speechBubble.material.opacity = 1 - bubbleProgress;
      if (bubbleProgress >= 1) {
        this.mesh.remove(this.speechBubble);
        this.speechBubble.material.dispose();
        this.speechBubble = null;
      }
    }
  }

  private createBody(): THREE.Group {
    const group = new THREE.Group();

    const jerseyMat = new THREE.MeshStandardMaterial({
      color: this.teamColor, roughness: 0.5, metalness: 0.05,
    });
    const jersey = new THREE.Mesh(new THREE.CylinderGeometry(0.30, 0.34, 0.50, 12), jerseyMat);
    jersey.castShadow = true;

    const numCanvas = document.createElement('canvas');
    numCanvas.width = 32;
    numCanvas.height = 40;
    const ctx = numCanvas.getContext('2d')!;
    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    ctx.font = 'bold 28px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(this.playerNumber, 16, 20);
    const numTex = new THREE.CanvasTexture(numCanvas);
    const numMat = new THREE.MeshBasicMaterial({
      map: numTex, transparent: true, depthTest: false, side: THREE.FrontSide,
    });
    const numMesh = new THREE.Mesh(new THREE.PlaneGeometry(0.14, 0.18), numMat);
    numMesh.position.set(0, 0.08, 0.32);
    jersey.add(numMesh);

    group.add(jersey);

    const shortsMat = new THREE.MeshStandardMaterial({
      color: this.shortsColor, roughness: 0.6, metalness: 0.05,
    });
    const shorts = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.28, 0.24, 12), shortsMat);
    shorts.position.y = -0.34;
    shorts.castShadow = true;
    group.add(shorts);

    return group;
  }

  private createHead(): THREE.Group {
    const group = new THREE.Group();

    const skinMat = new THREE.MeshStandardMaterial({ color: 0xffcc99, roughness: 0.6 });
    const hairMat = new THREE.MeshStandardMaterial({ color: 0x553322, roughness: 0.9 });
    const whiteMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const blackMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.09, 0.08, 8), skinMat);
    neck.position.y = -0.18;
    neck.castShadow = true;
    group.add(neck);

    const head = new THREE.Mesh(new THREE.SphereGeometry(0.20, 16, 12), skinMat);
    head.castShadow = true;
    group.add(head);

    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.20, 16, 12), hairMat);
    hair.position.y = 0.06;
    hair.scale.set(1.05, 0.30, 1.05);
    group.add(hair);

    const eyeGeo = new THREE.SphereGeometry(0.035, 8, 8);
    const pupilGeo = new THREE.SphereGeometry(0.018, 8, 8);

    const leftEye = new THREE.Mesh(eyeGeo, whiteMat);
    leftEye.position.set(-0.09, 0.04, 0.18);
    group.add(leftEye);

    const leftPupil = new THREE.Mesh(pupilGeo, blackMat);
    leftPupil.position.set(-0.09, 0.04, 0.21);
    group.add(leftPupil);

    const rightEye = new THREE.Mesh(eyeGeo, whiteMat);
    rightEye.position.set(0.09, 0.04, 0.18);
    group.add(rightEye);

    const rightPupil = new THREE.Mesh(pupilGeo, blackMat);
    rightPupil.position.set(0.09, 0.04, 0.21);
    group.add(rightPupil);

    const noseMat = new THREE.MeshStandardMaterial({ color: 0xeebb88, roughness: 0.6 });
    const nose = new THREE.Mesh(new THREE.SphereGeometry(0.025, 8, 8), noseMat);
    nose.position.set(0, -0.02, 0.20);
    group.add(nose);

    const earGeo = new THREE.SphereGeometry(0.03, 8, 8);

    const leftEar = new THREE.Mesh(earGeo, skinMat);
    leftEar.position.set(-0.20, 0, 0);
    leftEar.scale.z = 0.4;
    group.add(leftEar);

    const rightEar = new THREE.Mesh(earGeo, skinMat);
    rightEar.position.set(0.20, 0, 0);
    rightEar.scale.z = 0.4;
    group.add(rightEar);

    return group;
  }

  private createArm(): THREE.Group {
    const group = new THREE.Group();

    const armMat = new THREE.MeshStandardMaterial({
      color: this.teamColor, roughness: 0.5, metalness: 0.05,
    });
    const sleeve = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.08, 0.16, 8), armMat);
    sleeve.position.y = -0.10;
    sleeve.castShadow = true;
    group.add(sleeve);

    const skinMat = new THREE.MeshStandardMaterial({ color: 0xffcc99, roughness: 0.6 });
    const forearm = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.06, 0.18, 8), skinMat);
    forearm.position.y = -0.28;
    forearm.castShadow = true;
    group.add(forearm);

    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.045, 8, 8), skinMat);
    hand.position.y = -0.44;
    group.add(hand);

    return group;
  }

  private createLeg(): THREE.Group {
    const group = new THREE.Group();

    const skinMat = new THREE.MeshStandardMaterial({ color: 0xffcc99, roughness: 0.6 });
    const sockMat = new THREE.MeshStandardMaterial({
      color: this.teamColor, roughness: 0.5, metalness: 0.05,
    });
    const bootMat = new THREE.MeshStandardMaterial({
      color: 0x222222, roughness: 0.5, metalness: 0.1,
    });

    const thigh = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.10, 0.20, 8), skinMat);
    thigh.position.y = -0.10;
    thigh.castShadow = true;
    group.add(thigh);

    const sock = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.08, 0.18, 8), sockMat);
    sock.position.y = -0.28;
    sock.castShadow = true;
    group.add(sock);

    const boot = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 0.18), bootMat);
    boot.position.set(0, -0.44, 0.02);
    boot.castShadow = true;
    group.add(boot);

    return group;
  }

  private createNameLabel(): THREE.Sprite {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 64;
    const ctx = canvas.getContext('2d')!;
    ctx.font = 'bold 24px Arial';
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    const textW = ctx.measureText(this.playerName).width + 40;
    ctx.beginPath();
    ctx.roundRect(128 - textW / 2, 8, textW, 44, 22);
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(this.playerName, 128, 30);
    const tex = new THREE.CanvasTexture(canvas);
    const mat = new THREE.SpriteMaterial({
      map: tex, transparent: true, depthTest: false, sizeAttenuation: true,
    });
    const sprite = new THREE.Sprite(mat);
    sprite.scale.set(1.5, 0.4, 1);
    sprite.position.set(0, 1.3, 0);
    sprite.renderOrder = 999;
    this.mesh.add(sprite);
    return sprite;
  }

  sync(state: BikeState, dt: number = 1 / 60) {
    this.mesh.position.set(state.position.x, state.position.y, state.position.z);
    this.mesh.rotation.set(state.rotation.x, state.rotation.y, state.rotation.z);
    this.body.position.set(state.position.x, state.position.y, state.position.z);

    const speed = Math.sqrt(state.velocity.x ** 2 + state.velocity.z ** 2);
    const normalizedSpeed = Math.min(1, speed / 35);
    const speedFactor = Math.max(normalizedSpeed, 0.1);

    if (this.isCelebrating) {
      this.updateCelebration(dt);
    } else if (normalizedSpeed > 0.05) {
      this.animPhase += normalizedSpeed * 0.15;
    }

    if (!this.isCelebrating) {
      const sinPhase = Math.sin(this.animPhase);
      const cosPhase = Math.cos(this.animPhase);

      this.leftArm.rotation.x = sinPhase * 0.6 * speedFactor;
      this.rightArm.rotation.x = -sinPhase * 0.6 * speedFactor;
      this.leftLeg.rotation.x = sinPhase * 0.55 * speedFactor;
      this.rightLeg.rotation.x = -sinPhase * 0.55 * speedFactor;
    }
  }

  remove() {
    this.scene.remove(this.mesh);
    this.world.removeBody(this.body);
  }
}
