import { FieldColor } from '../../../shared/index.js';

const AUTH_KEY = 'football_auth';

interface AuthUser {
  name: string;
  photo: string;
  method: 'google' | 'guest';
}

function footballSvg(size: string): string {
  return `<svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}">
    <ellipse cx="100" cy="100" rx="70" ry="80" fill="white"/>
    <polygon points="100,50 128,72 118,106 82,106 72,72" fill="#dc2626" stroke="#dc2626" stroke-width="2.5"/>
    <line x1="100" y1="50" x2="100" y2="12" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <line x1="128" y1="72" x2="160" y2="56" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <line x1="118" y1="106" x2="148" y2="140" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <line x1="82" y1="106" x2="52" y2="140" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <line x1="72" y1="72" x2="40" y2="56" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <ellipse cx="100" cy="100" rx="68" ry="78" fill="none" stroke="#dc2626" stroke-width="2"/>
  </svg>`;
}

export { AUTH_KEY };
export type { AuthUser };

export class LoginScreen {
  private container: HTMLDivElement;
  private nameInput: HTMLInputElement;
  private statusEl: HTMLDivElement;
  private guestBtn: HTMLButtonElement;
  public googleBtnContainer: HTMLDivElement;

  public onLogin: ((user: AuthUser) => void) | null = null;

  constructor() {
    this.container = document.createElement('div');
    this.container.id = 'login-screen';
    this.container.style.cssText = `
      position: fixed; inset: 0; z-index: 600;
      display: flex; align-items: center; justify-content: center;
      background: linear-gradient(135deg, #dc2626 0%, #991b1b 50%, #7f1d1d 100%);
      font-family: 'Segoe UI', system-ui, sans-serif;
      transition: opacity 0.5s;
    `;

    // Animated background
    const bgDecor = document.createElement('div');
    bgDecor.style.cssText = `position: absolute; inset: 0; overflow: hidden; pointer-events: none;`;
    bgDecor.innerHTML = `
      <div style="position:absolute;top:-200px;left:-200px;width:600px;height:600px;
        background:radial-gradient(circle,rgba(255,255,255,0.06),transparent 70%);border-radius:50%;"></div>
      <div style="position:absolute;bottom:-200px;right:-200px;width:600px;height:600px;
        background:radial-gradient(circle,rgba(255,255,255,0.06),transparent 70%);border-radius:50%;"></div>
      <div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:800px;height:800px;
        background:radial-gradient(circle,rgba(255,255,255,0.03),transparent 60%);border-radius:50%;"></div>
      <div style="position:absolute;top:0;left:0;right:0;bottom:0;
        background-image:
          linear-gradient(rgba(255,255,255,0.04) 1px,transparent 1px),
          linear-gradient(90deg,rgba(255,255,255,0.04) 1px,transparent 1px);
        background-size: 60px 60px;"></div>
    `;
    this.container.appendChild(bgDecor);

    // Card
    const card = document.createElement('div');
    card.style.cssText = `
      position: relative; z-index: 1;
      display: flex; flex-direction: column; align-items: center;
      width: min(400px, 92vw);
    `;

    // Logo
    const logo = document.createElement('div');
    logo.style.cssText = `
      margin-bottom: 0.2rem;
      filter: drop-shadow(0 0 50px rgba(255,255,255,0.3));
      animation: pulseGlow 3s ease-in-out infinite;
    `;
    logo.innerHTML = footballSvg('clamp(100px, 25vw, 160px)');

    const title = document.createElement('h1');
    title.style.cssText = `
      font-size: clamp(1.8rem, 7vw, 3rem); font-weight: 900; letter-spacing: -1px;
      color: #fff; margin-bottom: 0.1rem; text-align: center;
    `;
    title.textContent = '6x6 FOOTBALL';

    const subtitle = document.createElement('p');
    subtitle.style.cssText = `
      font-size: clamp(0.5rem, 2.5vw, 0.75rem); color: rgba(255,255,255,0.5);
      margin-bottom: 2rem; letter-spacing: 5px; text-transform: uppercase;
    `;
    subtitle.textContent = '6v6 Football';

    // Google Sign-In button
    this.googleBtnContainer = document.createElement('div');
    this.googleBtnContainer.style.cssText = `margin-bottom: 12px; width: 100%; display: flex; justify-content: center;`;

    const googleBtn = document.createElement('div');
    googleBtn.className = 'g_id_signin';
    googleBtn.setAttribute('data-type', 'standard');
    googleBtn.setAttribute('data-shape', 'pill');
    googleBtn.setAttribute('data-theme', 'filled_black');
    googleBtn.setAttribute('data-text', 'signin_with');
    googleBtn.setAttribute('data-size', 'large');
    googleBtn.setAttribute('data-logo_alignment', 'left');
    this.googleBtnContainer.appendChild(googleBtn);

    // Or divider
    const orDiv = document.createElement('div');
    orDiv.style.cssText = `
      display: flex; align-items: center; gap: 12px; width: 100%; margin: 12px 0;
      color: rgba(255,255,255,0.3); font-size: 0.65rem; letter-spacing: 1px;
    `;
    const l1 = document.createElement('div');
    l1.style.cssText = `flex:1; height:1px; background: rgba(255,255,255,0.1);`;
    const ot = document.createElement('span');
    ot.textContent = 'OR';
    const l2 = document.createElement('div');
    l2.style.cssText = `flex:1; height:1px; background: rgba(255,255,255,0.1);`;
    orDiv.appendChild(l1);
    orDiv.appendChild(ot);
    orDiv.appendChild(l2);

    // Name input for Guest
    const guestLabel = document.createElement('div');
    guestLabel.style.cssText = `color: rgba(255,255,255,0.4); font-size: 0.7rem; letter-spacing: 1px; margin-bottom: 6px; text-transform: uppercase;`;
    guestLabel.textContent = 'Play as Guest';

    this.nameInput = document.createElement('input');
    this.nameInput.type = 'text';
    this.nameInput.placeholder = 'Enter your name';
    this.nameInput.maxLength = 16;
    this.nameInput.style.cssText = `
      background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.2);
      color: #fff; padding: 10px 20px; font-size: 0.9rem; border-radius: 8px;
      outline: none; width: 100%; text-align: center; box-sizing: border-box;
      transition: border-color 0.3s;
    `;
    this.nameInput.addEventListener('focus', () => this.nameInput.style.borderColor = '#fff');
    this.nameInput.addEventListener('blur', () => this.nameInput.style.borderColor = 'rgba(255,255,255,0.2)');

    const names = ['Striker', 'Blaze', 'Phantom', 'Nitro', 'Vortex', 'Fury', 'Shadow', 'Thunder', 'Ace', 'Bolt'];
    this.nameInput.value = names[Math.floor(Math.random() * names.length)] + Math.floor(Math.random() * 100);

    // Guest button
    this.guestBtn = document.createElement('button');
    this.guestBtn.textContent = 'PLAY AS GUEST';
    this.guestBtn.style.cssText = `
      background: rgba(255,255,255,0.12); border: 2px solid rgba(255,255,255,0.3);
      color: #fff; padding: 11px 24px; font-size: 0.85rem;
      font-weight: 700; border-radius: 8px; cursor: pointer;
      transition: all 0.3s; letter-spacing: 1px; width: 100%;
      margin-top: 8px;
      backdrop-filter: blur(4px);
    `;
    this.guestBtn.addEventListener('mouseenter', () => {
      this.guestBtn.style.background = 'rgba(255,255,255,0.2)';
    });
    this.guestBtn.addEventListener('mouseleave', () => {
      this.guestBtn.style.background = 'rgba(255,255,255,0.12)';
    });
    this.guestBtn.addEventListener('click', () => {
      const name = this.nameInput.value.trim() || 'Player';
      this.onLogin?.({ name, photo: '', method: 'guest' });
    });

    // Status
    this.statusEl = document.createElement('div');
    this.statusEl.style.cssText = `margin-top: 12px; color: rgba(255,255,255,0.5); font-size: 0.75rem; height: 1.2em;`;

    card.appendChild(logo);
    card.appendChild(title);
    card.appendChild(subtitle);
    card.appendChild(this.googleBtnContainer);
    card.appendChild(orDiv);
    card.appendChild(guestLabel);
    card.appendChild(this.nameInput);
    card.appendChild(this.guestBtn);
    card.appendChild(this.statusEl);

    this.container.appendChild(card);

    // Pulse glow animation
    const style = document.createElement('style');
    style.textContent = `
      @keyframes pulseGlow {
        0%, 100% { filter: drop-shadow(0 0 40px rgba(255,255,255,0.2)); }
        50% { filter: drop-shadow(0 0 60px rgba(255,255,255,0.4)); }
      }
    `;
    document.head.appendChild(style);

    document.body.appendChild(this.container);
  }

  setStatus(msg: string) {
    this.statusEl.textContent = msg;
  }

  show() {
    this.container.style.display = 'flex';
    this.container.style.opacity = '1';
  }

  hide() {
    this.container.style.opacity = '0';
    setTimeout(() => { this.container.style.display = 'none'; }, 500);
  }

  destroy() {
    this.container.remove();
  }
}
