import { FieldColor } from '../../../shared/index.js';

function footballSvg(size: string): string {
  return `<svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}">
    <ellipse cx="100" cy="100" rx="70" ry="80" fill="white"/>
    <polygon points="100,50 128,72 118,106 82,106 72,72" fill="#dc2626" stroke="#dc2626" stroke-width="2.5"/>
    <line x1="100" y1="50" x2="100" y2="12" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <line x1="128" y1="72" x2="160" y2="56" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <line x1="118" y1="106" x2="148" y2="140" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <line x1="82" y1="106" x2="52" y2="140" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <line x1="72" y1="72" x2="40" y2="56" stroke="#dc2626" stroke-width="3" stroke-linecap="round"/>
    <ellipse cx="100" cy="100" rx="68" ry="78" fill="none" stroke="#dc2626" stroke-width="2"/>
  </svg>`;
}

export class DashboardScreen {
  private container: HTMLDivElement;
  private userPhotoEl: HTMLDivElement;
  private userNameEl: HTMLDivElement;
  private colorSwatches: HTMLDivElement;
  private colorSection: HTMLDivElement;
  private selectedColor: FieldColor = FieldColor.Green;
  private mainCards: HTMLDivElement;
  private teamModal: HTMLDivElement;

  public onCreateRoom: (() => void) | null = null;
  public onPractice: ((team: 'blue' | 'red') => void) | null = null;
  public onSettings: (() => void) | null = null;
  public onGuide: (() => void) | null = null;
  public onExit: (() => void) | null = null;
  public onColorChange: ((color: FieldColor) => void) | null = null;

  constructor() {
    this.container = document.createElement('div');
    this.container.id = 'dashboard-screen';
    this.container.style.cssText = `
      position: fixed; inset: 0; z-index: 550;
      display: none; flex-direction: column;
      background: linear-gradient(135deg, #05050a 0%, #0d0d2b 100%);
      font-family: 'Segoe UI', system-ui, sans-serif;
      padding: max(20px, env(safe-area-inset-top, 0px) + 10px)
               max(16px, env(safe-area-inset-right, 0px))
               max(20px, env(safe-area-inset-bottom, 0px))
               max(16px, env(safe-area-inset-left, 0px));
      transition: opacity 0.3s;
      overflow-y: auto;
    `;

    // Animated background
    const bg = document.createElement('div');
    bg.style.cssText = `position: absolute; inset: 0; overflow: hidden; pointer-events: none;`;
    bg.innerHTML = `
      <div style="position:absolute;top:-300px;right:-200px;width:500px;height:500px;
        background:radial-gradient(circle,rgba(0,240,255,0.06),transparent 70%);border-radius:50%;"></div>
      <div style="position:absolute;bottom:-200px;left:-200px;width:500px;height:500px;
        background:radial-gradient(circle,rgba(139,92,246,0.06),transparent 70%);border-radius:50%;"></div>
    `;
    this.container.appendChild(bg);

    // Header row
    const header = document.createElement('div');
    header.style.cssText = `
      position: relative; z-index: 1;
      display: flex; align-items: center; gap: 12px;
      padding: 16px 0 20px;
    `;

    this.userPhotoEl = document.createElement('div');
    this.userPhotoEl.style.cssText = `
      width: 44px; height: 44px; border-radius: 50%;
      background: linear-gradient(135deg, #dc2626, #991b1b);
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0; overflow: hidden;
    `;
    this.userPhotoEl.innerHTML = footballSvg('30px');

    const userInfo = document.createElement('div');
    userInfo.style.cssText = `flex: 1; min-width: 0;`;

    this.userNameEl = document.createElement('div');
    this.userNameEl.style.cssText = `
      font-size: 1.2rem; font-weight: 700; color: #fff;
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    `;
    this.userNameEl.textContent = 'Player';

    const sub = document.createElement('div');
    sub.style.cssText = `color: rgba(0,240,255,0.4); font-size: 0.65rem; letter-spacing: 1px; text-transform: uppercase;`;
    sub.textContent = 'Ready to play';

    userInfo.appendChild(this.userNameEl);
    userInfo.appendChild(sub);

    header.appendChild(this.userPhotoEl);
    header.appendChild(userInfo);
    this.container.appendChild(header);

    // Main cards grid (2x2)
    this.mainCards = document.createElement('div');
    this.mainCards.style.cssText = `
      position: relative; z-index: 1;
      display: grid; grid-template-columns: 1fr 1fr; gap: 12px;
      flex: 1;
    `;

    const cards: { icon: string; label: string; accent: string; action: () => void }[] = [
      { icon: '🏠', label: 'Create Room', accent: '#00f0ff', action: () => this.onCreateRoom?.() },
      { icon: '🎨', label: 'Ground Color', accent: '#8b5cf6', action: () => this.toggleColorPicker() },
      { icon: '⚙️', label: 'Settings', accent: '#fbbf24', action: () => this.onSettings?.() },
      { icon: '📖', label: 'Guide', accent: '#22c55e', action: () => this.onGuide?.() },
    ];

    cards.forEach((c) => {
      const card = document.createElement('div');
      card.style.cssText = `
        background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.06);
        border-radius: 20px; padding: 24px 16px;
        display: flex; flex-direction: column; align-items: center; justify-content: center;
        gap: 12px; cursor: pointer; transition: all 0.3s;
        backdrop-filter: blur(12px); min-height: 140px;
        -webkit-tap-highlight-color: transparent;
      `;
      card.addEventListener('mouseenter', () => {
        card.style.borderColor = c.accent;
        card.style.background = `rgba(255,255,255,0.04)`;
      });
      card.addEventListener('mouseleave', () => {
        card.style.borderColor = 'rgba(255,255,255,0.06)';
        card.style.background = 'rgba(255,255,255,0.02)';
      });
      card.addEventListener('click', c.action);

      const icon = document.createElement('div');
      icon.style.cssText = `font-size: 2rem;`;
      icon.textContent = c.icon;

      const label = document.createElement('div');
      label.style.cssText = `
        font-size: 0.8rem; font-weight: 700; color: ${c.accent};
        letter-spacing: 1px; text-align: center;
      `;
      label.textContent = c.label;

      card.appendChild(icon);
      card.appendChild(label);
      this.mainCards.appendChild(card);
    });

    this.container.appendChild(this.mainCards);

    // Practice vs AI button row
    const practiceBtn = document.createElement('button');
    practiceBtn.innerHTML = '⚡ Practice vs AI';
    practiceBtn.style.cssText = `
      position: relative; z-index: 1;
      background: linear-gradient(135deg, #f59e0b, #ef4444);
      color: #fff; border: none; padding: 16px 24px; margin-top: 12px;
      font-size: 1rem; font-weight: 800; border-radius: 16px;
      letter-spacing: 1px; cursor: pointer; transition: all 0.3s;
      width: 100%; text-align: center;
      -webkit-tap-highlight-color: transparent;
    `;
    practiceBtn.addEventListener('mouseenter', () => {
      practiceBtn.style.transform = 'scale(1.02)';
      practiceBtn.style.boxShadow = '0 0 30px rgba(239,68,68,0.3)';
    });
    practiceBtn.addEventListener('mouseleave', () => {
      practiceBtn.style.transform = '';
      practiceBtn.style.boxShadow = '';
    });
    practiceBtn.addEventListener('click', () => this.showTeamModal());
    this.container.appendChild(practiceBtn);

    // Team select modal
    this.teamModal = document.createElement('div');
    this.teamModal.style.cssText = `
      position: fixed; inset: 0; z-index: 700;
      display: none; align-items: center; justify-content: center;
      background: rgba(0,0,0,0.7);
      backdrop-filter: blur(8px);
      font-family: 'Segoe UI', system-ui, sans-serif;
    `;

    const modalCard = document.createElement('div');
    modalCard.style.cssText = `
      background: linear-gradient(135deg, #05050a 0%, #0d0d2b 100%);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: 24px; padding: 32px; width: min(340px, 88vw);
      text-align: center;
    `;

    const modalTitle = document.createElement('div');
    modalTitle.style.cssText = `
      font-size: 1.3rem; font-weight: 900; margin-bottom: 4px;
      background: linear-gradient(135deg, #f59e0b, #ef4444);
      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    `;
    modalTitle.textContent = 'Choose Your Team';

    const modalSub = document.createElement('div');
    modalSub.style.cssText = `color: rgba(255,255,255,0.3); font-size: 0.75rem; margin-bottom: 24px; letter-spacing: 1px;`;
    modalSub.textContent = 'Practice against 11 AI opponents';

    const btnRow = document.createElement('div');
    btnRow.style.cssText = `display: flex; gap: 12px;`;

    const blueBtn = document.createElement('button');
    blueBtn.innerHTML = '🔵 BLUE';
    blueBtn.style.cssText = `
      flex: 1; padding: 18px 0; border-radius: 14px; border: none;
      background: linear-gradient(135deg, #00f0ff, #0ea5e9);
      color: #fff; font-size: 1rem; font-weight: 800; letter-spacing: 2px;
      cursor: pointer; transition: all 0.2s;
      -webkit-tap-highlight-color: transparent;
    `;
    blueBtn.addEventListener('mouseenter', () => {
      blueBtn.style.transform = 'scale(1.05)';
    });
    blueBtn.addEventListener('mouseleave', () => {
      blueBtn.style.transform = '';
    });
    blueBtn.addEventListener('click', () => {
      this.hideTeamModal();
      this.onPractice?.('blue');
    });

    const redBtn = document.createElement('button');
    redBtn.innerHTML = '🔴 RED';
    redBtn.style.cssText = `
      flex: 1; padding: 18px 0; border-radius: 14px; border: none;
      background: linear-gradient(135deg, #ef4444, #dc2626);
      color: #fff; font-size: 1rem; font-weight: 800; letter-spacing: 2px;
      cursor: pointer; transition: all 0.2s;
      -webkit-tap-highlight-color: transparent;
    `;
    redBtn.addEventListener('mouseenter', () => {
      redBtn.style.transform = 'scale(1.05)';
    });
    redBtn.addEventListener('mouseleave', () => {
      redBtn.style.transform = '';
    });
    redBtn.addEventListener('click', () => {
      this.hideTeamModal();
      this.onPractice?.('red');
    });

    // Close modal on backdrop click
    this.teamModal.addEventListener('click', (e) => {
      if (e.target === this.teamModal) this.hideTeamModal();
    });

    btnRow.appendChild(blueBtn);
    btnRow.appendChild(redBtn);
    modalCard.appendChild(modalTitle);
    modalCard.appendChild(modalSub);
    modalCard.appendChild(btnRow);
    this.teamModal.appendChild(modalCard);
    this.container.appendChild(this.teamModal);

    // Color picker section (hidden by default)
    this.colorSection = document.createElement('div');
    this.colorSection.style.cssText = `
      position: relative; z-index: 1;
      display: none; flex-direction: column; align-items: center;
      margin-top: 12px; padding: 16px;
      background: rgba(255,255,255,0.02); border-radius: 16px;
      border: 1px solid rgba(255,255,255,0.06);
    `;

    const colorTitle = document.createElement('div');
    colorTitle.style.cssText = `color: rgba(255,255,255,0.4); font-size: 0.65rem; letter-spacing: 1px; margin-bottom: 10px; text-transform: uppercase;`;
    colorTitle.textContent = 'Select Pitch Color';

    this.colorSwatches = document.createElement('div');
    this.colorSwatches.style.cssText = `display: flex; gap: 14px; justify-content: center;`;

    const colors: { key: FieldColor; bg: string; label: string }[] = [
      { key: FieldColor.Green, bg: 'linear-gradient(135deg, #1a8a3a, #2a9a4a)', label: 'Green' },
      { key: FieldColor.Clay, bg: 'linear-gradient(135deg, #c47a3a, #d48a4a)', label: 'Clay' },
      { key: FieldColor.Dark, bg: 'linear-gradient(135deg, #1a1a2e, #2a2a3e)', label: 'Dark' },
    ];

    colors.forEach((c) => {
      const swatch = document.createElement('button');
      const isActive = c.key === this.selectedColor;
      swatch.style.cssText = `
        width: 48px; height: 48px; border-radius: 50%;
        background: ${c.bg}; border: 2px solid ${isActive ? '#00f0ff' : 'rgba(255,255,255,0.1)'};
        cursor: pointer; transition: all 0.2s; outline: none;
        box-shadow: ${isActive ? '0 0 16px rgba(0,240,255,0.3)' : 'none'};
        -webkit-tap-highlight-color: transparent;
      `;
      swatch.title = c.label;
      swatch.addEventListener('click', () => {
        this.selectedColor = c.key;
        this.updateSwatches(colors);
        this.onColorChange?.(c.key);
      });
      this.colorSwatches.appendChild(swatch);
    });

    this.colorSection.appendChild(colorTitle);
    this.colorSection.appendChild(this.colorSwatches);
    this.container.appendChild(this.colorSection);

    // Exit button — bottom-right
    const exitBtn = document.createElement('button');
    exitBtn.textContent = '🚪 EXIT';
    exitBtn.style.cssText = `
      position: fixed;
      bottom: max(20px, env(safe-area-inset-bottom, 0px) + 10px);
      right: max(16px, env(safe-area-inset-right, 0px) + 10px);
      z-index: 2;
      background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1);
      color: rgba(255,255,255,0.5); padding: 10px 20px; font-size: 0.8rem;
      font-weight: 600; border-radius: 10px; cursor: pointer;
      transition: all 0.2s; letter-spacing: 1px;
      backdrop-filter: blur(8px);
      -webkit-tap-highlight-color: transparent;
    `;
    exitBtn.addEventListener('mouseenter', () => {
      exitBtn.style.background = 'rgba(239,68,68,0.15)';
      exitBtn.style.borderColor = '#ef4444';
      exitBtn.style.color = '#ef4444';
    });
    exitBtn.addEventListener('mouseleave', () => {
      exitBtn.style.background = 'rgba(255,255,255,0.05)';
      exitBtn.style.borderColor = 'rgba(255,255,255,0.1)';
      exitBtn.style.color = 'rgba(255,255,255,0.5)';
    });
    exitBtn.addEventListener('click', () => this.onExit?.());
    this.container.appendChild(exitBtn);

    document.body.appendChild(this.container);
  }

  private updateSwatches(colors: { key: FieldColor; bg: string }[]) {
    const swatches = this.colorSwatches.querySelectorAll('button');
    swatches.forEach((swatch, i) => {
      const el = swatch as HTMLButtonElement;
      const isActive = colors[i].key === this.selectedColor;
      el.style.borderColor = isActive ? '#00f0ff' : 'rgba(255,255,255,0.1)';
      el.style.boxShadow = isActive ? '0 0 16px rgba(0,240,255,0.3)' : 'none';
    });
  }

  private toggleColorPicker() {
    const isHidden = this.colorSection.style.display === 'none';
    this.colorSection.style.display = isHidden ? 'flex' : 'none';
  }

  setColor(color: FieldColor) {
    this.selectedColor = color;
  }

  private showTeamModal() {
    this.teamModal.style.display = 'flex';
  }

  private hideTeamModal() {
    this.teamModal.style.display = 'none';
  }

  setUser(name: string, photo: string) {
    this.userNameEl.textContent = name;
    if (photo) {
      this.userPhotoEl.style.background = 'transparent';
      this.userPhotoEl.innerHTML = `<img src="${photo}" style="width:100%;height:100%;border-radius:50%;object-fit:cover;" />`;
    } else {
      this.userPhotoEl.style.background = 'linear-gradient(135deg, #dc2626, #991b1b)';
      this.userPhotoEl.innerHTML = footballSvg('30px');
    }
  }

  show() {
    this.container.style.display = 'flex';
    this.container.style.opacity = '1';
  }

  hide() {
    this.container.style.opacity = '0';
    setTimeout(() => { this.container.style.display = 'none'; }, 300);
  }
}
