import {
  PlayerState, PlayerInput, BallState, MatchState, MatchConfig,
  Team, TeamMode, BikeState,
  FIELD, BIKE, BALL,
} from '../../../shared/index.js';

interface LocalMatch {
  id: string;
  state: MatchState;
  config: MatchConfig;
  players: Map<string, PlayerState>;
  ball: BallState;
  blueScore: number;
  redScore: number;
  elapsedSeconds: number;
  kickoffTimer: number;
  lastInputs: Map<string, PlayerInput>;
  lastUpdateTime: number;
  goalScoredTimer: number;
  ended: boolean;
  teamMode: { blue: TeamMode; red: TeamMode };
}

export interface LocalMatchCallbacks {
  onMatchFound: (data: { matchId: string; config: MatchConfig; teamMode: { blue: TeamMode; red: TeamMode }; playerId: string }) => void;
  onStateUpdate: (data: any) => void;
  onGoalScored: (data: { team: Team; blueScore: number; redScore: number; scorer: string | null }) => void;
  onMatchEnd: (data: { blueScore: number; redScore: number; winner: Team | null }) => void;
  onCountdown: (data: { time: number }) => void;
}

let matchCounter = 0;

export class LocalMatchManager {
  private match: LocalMatch | null = null;
  private tickInterval: number | null = null;
  private countdownInterval: number | null = null;
  private playerName: string;
  private humanPlayerId: string;
  private callbacks: LocalMatchCallbacks;

  constructor(playerName: string, callbacks: LocalMatchCallbacks) {
    this.playerName = playerName;
    this.humanPlayerId = `local_${Date.now()}`;
    this.callbacks = callbacks;
  }

  startPractice(team: 'blue' | 'red') {
    matchCounter++;
    const matchId = `local_practice_${matchCounter}`;
    const match: LocalMatch = {
      id: matchId,
      state: MatchState.Kickoff,
      config: {
        maxGoals: 5,
        timeLimitSeconds: 300,
        teams: 2,
        playersPerTeam: 6,
      },
      players: new Map(),
      ball: {
        position: { x: 0, y: BALL.RADIUS, z: 0 },
        velocity: { x: 0, y: 0, z: 0 },
        lastTouchBy: null,
      },
      blueScore: 0,
      redScore: 0,
      elapsedSeconds: 0,
      kickoffTimer: 3,
      lastInputs: new Map(),
      lastUpdateTime: Date.now(),
      goalScoredTimer: 0,
      ended: false,
      teamMode: { blue: 'normal', red: 'normal' },
    };

    const chosenTeam = team === 'blue' ? Team.Blue : Team.Red;
    const teamCounts = new Map<Team, number>();
    const humanTeamIndex = team === 'blue' ? 0 : 6;

    for (let i = 0; i < 12; i++) {
      let playerState: PlayerState;
      const isHumanSlot = i === humanTeamIndex;

      if (isHumanSlot) {
        const count = teamCounts.get(chosenTeam) || 0;
        teamCounts.set(chosenTeam, count + 1);
        const pos = this.getFormationPosition(chosenTeam, count);
        playerState = {
          id: this.humanPlayerId,
          name: this.playerName,
          team: chosenTeam,
          isAI: false,
          bike: {
            position: pos,
            rotation: { x: 0, y: chosenTeam === Team.Blue ? 0 : Math.PI, z: 0 },
            velocity: { x: 0, y: 0, z: 0 },
            angularVelocity: { x: 0, y: 0, z: 0 },
            boost: BIKE.BOOST_MAX,
            isGrounded: true,
            isBoosting: false,
          },
          connected: true,
          jerseyNumber: count + 1,
        };
      } else {
        const playerTeam: Team = i < 6 ? Team.Blue : Team.Red;
        const teamIndex = i < 6 ? i : i - 6;
        const aiId = `ai_${matchId}_${i}`;
        const aiName = `AI_${teamIndex + 1}`;
        const pos = this.getFormationPosition(playerTeam, teamIndex);
        playerState = {
          id: aiId,
          name: aiName,
          team: playerTeam,
          isAI: true,
          bike: {
            position: pos,
            rotation: { x: 0, y: playerTeam === Team.Blue ? 0 : Math.PI, z: 0 },
            velocity: { x: 0, y: 0, z: 0 },
            angularVelocity: { x: 0, y: 0, z: 0 },
            boost: BIKE.BOOST_MAX,
            isGrounded: true,
            isBoosting: false,
          },
          connected: false,
          jerseyNumber: teamIndex + 1,
        };
        teamCounts.set(playerTeam, (teamCounts.get(playerTeam) || 0) + 1);
      }

      match.players.set(playerState.id, playerState);
    }

    match.teamMode = {
      blue: chosenTeam === Team.Blue ? 'attack' : 'defence',
      red: chosenTeam === Team.Red ? 'attack' : 'defence',
    };

    this.resetPositions(match);
    this.match = match;

    this.callbacks.onMatchFound({
      matchId,
      config: match.config,
      teamMode: match.teamMode,
      playerId: this.humanPlayerId,
    });

    this.broadcastState(match);
    this.startKickoffCountdown(match);
    this.startTicks();
  }

  handleInput(input: PlayerInput) {
    if (!this.match) return;
    this.match.lastInputs.set(this.humanPlayerId, input);
  }

  sendTeamMode(mode: TeamMode) {
    if (!this.match) return;
    const player = this.match.players.get(this.humanPlayerId);
    if (!player) return;
    this.match.teamMode[player.team] = mode;
  }

  destroy() {
    if (this.tickInterval !== null) {
      clearInterval(this.tickInterval);
      this.tickInterval = null;
    }
    if (this.countdownInterval !== null) {
      clearInterval(this.countdownInterval);
      this.countdownInterval = null;
    }
    this.match = null;
  }

  private startTicks() {
    this.tickInterval = window.setInterval(() => this.tick(), 1000 / 30);
  }

  private startKickoffCountdown(match: LocalMatch) {
    match.state = MatchState.Kickoff;
    match.kickoffTimer = 3;
    this.broadcastState(match);
    console.log('[DIAG] Kickoff countdown started, timer=3');

    this.countdownInterval = window.setInterval(() => {
      if (!this.match) { this.clearCountdown(); return; }
      match.kickoffTimer--;
      console.log('[DIAG] Kickoff countdown tick:', match.kickoffTimer);
      this.callbacks.onCountdown({ time: match.kickoffTimer });

      if (match.kickoffTimer <= 0) {
        this.clearCountdown();
        match.state = MatchState.Playing;
        console.log('[DIAG] State transitioned to Playing');
        this.broadcastState(match);
      }
    }, 1000);
  }

  private clearCountdown() {
    if (this.countdownInterval !== null) {
      clearInterval(this.countdownInterval);
      this.countdownInterval = null;
    }
  }

  private tick() {
    const match = this.match;
    if (!match) return;
    if (match.state !== MatchState.Playing && match.state !== MatchState.Kickoff) return;

    const now = Date.now();
    const dt = Math.min((now - match.lastUpdateTime) / 1000, 0.05);
    match.lastUpdateTime = now;

    if (match.state === MatchState.Kickoff) {
      console.log('[DIAG] tick in Kickoff state (simulatePlayers SKIPPED)');
    }

    if (match.state === MatchState.Playing) {
      match.elapsedSeconds += dt;

      const humanInput = match.lastInputs.get(this.humanPlayerId);
      if (humanInput) {
        console.log('[DIAG] tick humanInput:', JSON.stringify({
          steer: humanInput.steer, throttle: humanInput.throttle,
          kick: humanInput.kick, sprint: humanInput.sprint,
        }));
      } else {
        console.log('[DIAG] tick NO humanInput stored for', this.humanPlayerId);
      }

      if (match.config.timeLimitSeconds && match.elapsedSeconds >= match.config.timeLimitSeconds) {
        this.endMatch(match);
        return;
      }

      this.simulateAI(match, dt);
      this.simulatePlayers(match, dt);
    }

    this.simulateBall(match, dt);
    this.broadcastState(match);
  }

  private simulateBall(match: LocalMatch, dt: number) {
    const ball = match.ball;
    ball.velocity.y -= 9.81 * dt;

    ball.position.x += ball.velocity.x * dt;
    ball.position.y += ball.velocity.y * dt;
    ball.position.z += ball.velocity.z * dt;

    if (ball.position.y < BALL.RADIUS) {
      ball.position.y = BALL.RADIUS;
      ball.velocity.y *= -BALL.BOUNCE;
      ball.velocity.x *= (1 - BALL.FRICTION * dt);
      ball.velocity.z *= (1 - BALL.FRICTION * dt);
    }

    const halfLength = FIELD.LENGTH / 2;
    const halfWidth = FIELD.WIDTH / 2;

    const inGoalX = Math.abs(ball.position.x) > halfLength - FIELD.GOAL_DEPTH;
    const inGoalZ = Math.abs(ball.position.z) < FIELD.GOAL_WIDTH / 2;
    const inGoalY = ball.position.y < FIELD.GOAL_HEIGHT;

    if (inGoalX && inGoalZ && inGoalY) {
      const scoringTeam = ball.position.x > 0 ? Team.Red : Team.Blue;
      this.handleGoal(match, scoringTeam);
      return;
    }

    if (Math.abs(ball.position.x) > halfLength) {
      ball.position.x = Math.sign(ball.position.x) * halfLength;
      ball.velocity.x *= -BALL.BOUNCE;
    }
    if (Math.abs(ball.position.z) > halfWidth) {
      ball.position.z = Math.sign(ball.position.z) * halfWidth;
      ball.velocity.z *= -BALL.BOUNCE;
    }
  }

  private handleGoal(match: LocalMatch, scoringTeam: Team) {
    if (scoringTeam === Team.Blue) match.blueScore++;
    else match.redScore++;

    match.state = MatchState.GoalScored;
    match.goalScoredTimer = 3;

    this.callbacks.onGoalScored({
      team: scoringTeam,
      blueScore: match.blueScore,
      redScore: match.redScore,
      scorer: match.ball.lastTouchBy,
    });

    if (match.config.maxGoals && (match.blueScore >= match.config.maxGoals || match.redScore >= match.config.maxGoals)) {
      setTimeout(() => this.endMatch(match), 3000);
    } else {
      setTimeout(() => {
        if (!this.match) return;
        this.resetPositions(match);
        this.startKickoffCountdown(match);
      }, 3000);
    }

    this.broadcastState(match);
  }

  private endMatch(match: LocalMatch) {
    match.state = MatchState.Ended;
    match.ended = true;
    this.broadcastState(match);

    this.callbacks.onMatchEnd({
      blueScore: match.blueScore,
      redScore: match.redScore,
      winner: match.blueScore > match.redScore ? Team.Blue :
              match.redScore > match.blueScore ? Team.Red : null,
    });
  }

  private simulatePlayers(match: LocalMatch, dt: number) {
    match.players.forEach((player) => {
      const input = match.lastInputs.get(player.id);
      if (!input && !player.isAI) return;
      if (!input) return;

      const bike = player.bike;
      const isBlue = player.team === Team.Blue;
      const dir = isBlue ? 1 : -1;

      const maxSpeed = input.sprint ? BIKE.BOOST_SPEED : BIKE.MAX_SPEED;
      const accel = input.sprint ? BIKE.BOOST_ACCELERATION : BIKE.ACCELERATION;

      if (input.throttle !== 0) {
        const forwardX = Math.sin(bike.rotation.y) * dir;
        const forwardZ = Math.cos(bike.rotation.y) * dir;

        bike.velocity.x += forwardX * accel * input.throttle * dt;
        bike.velocity.z += forwardZ * accel * input.throttle * dt;
      }

      if (input.throttle < 0) {
        bike.velocity.x *= (1 - BIKE.BRAKE_FORCE * dt);
        bike.velocity.z *= (1 - BIKE.BRAKE_FORCE * dt);
      }

      const speed = Math.sqrt(bike.velocity.x ** 2 + bike.velocity.z ** 2);
      if (Math.abs(input.steer) > 0.1 && speed > 0.5) {
        const turnRate = BIKE.STEER_SPEED * input.steer * (1 + speed / BIKE.MAX_SPEED * 0.5) * dt;
        bike.rotation.y += turnRate * dir;
        bike.angularVelocity.y = turnRate / dt;
      }

      bike.isBoosting = input.sprint && bike.boost > 0;
      if (bike.isBoosting) {
        bike.boost = Math.max(0, bike.boost - BIKE.BOOST_DRAIN_RATE * dt);
      } else {
        bike.boost = Math.min(BIKE.BOOST_MAX, bike.boost + BIKE.BOOST_REGEN_RATE * dt);
      }

      const friction = 2.0;
      bike.velocity.x *= (1 - friction * dt);
      bike.velocity.z *= (1 - friction * dt);

      const currentSpeed = Math.sqrt(bike.velocity.x ** 2 + bike.velocity.z ** 2);
      if (currentSpeed > maxSpeed) {
        const scale = maxSpeed / currentSpeed;
        bike.velocity.x *= scale;
        bike.velocity.z *= scale;
      }

      if (input.jump && bike.isGrounded) {
        bike.velocity.y = 8;
        bike.isGrounded = false;
      }

      if (!bike.isGrounded) {
        bike.velocity.y -= 15 * dt;
      }

      bike.position.x += bike.velocity.x * dt;
      bike.position.y += bike.velocity.y * dt;
      bike.position.z += bike.velocity.z * dt;

      if (bike.position.y <= 0.5) {
        bike.position.y = 0.5;
        bike.velocity.y = 0;
        bike.isGrounded = true;
        bike.angularVelocity.y *= 0.9;
      }

      const halfLength = FIELD.LENGTH / 2 - 0.5;
      const halfWidth = FIELD.WIDTH / 2 - 0.5;

      if (Math.abs(bike.position.x) > halfLength) {
        bike.position.x = Math.sign(bike.position.x) * halfLength;
        bike.velocity.x *= -0.3;
      }
      if (Math.abs(bike.position.z) > halfWidth) {
        bike.position.z = Math.sign(bike.position.z) * halfWidth;
        bike.velocity.z *= -0.3;
      }

      if (Math.abs(bike.position.x) > FIELD.LENGTH / 2 - FIELD.GOAL_DEPTH - 0.5) {
        if (Math.abs(bike.position.z) < FIELD.GOAL_WIDTH / 2 + 0.5 && bike.position.y < FIELD.GOAL_HEIGHT) {
          bike.position.x = Math.sign(bike.position.x) * (FIELD.LENGTH / 2 - FIELD.GOAL_DEPTH - 0.5);
          bike.velocity.x *= -0.3;
        }
      }

      if (input.kick) {
        const dx = bike.position.x - match.ball.position.x;
        const dz = bike.position.z - match.ball.position.z;
        const dist = Math.sqrt(dx * dx + dz * dz);

        if (dist < 3.0 && dist > 0) {
          let kickForce = input.pass ? 20 : 35;
          let forwardX: number;
          let forwardZ: number;

          if (input.kickDirection) {
            const kd = input.kickDirection;
            const kMag = Math.sqrt(kd.x * kd.x + kd.z * kd.z);
            if (kMag > 0.01) {
              forwardX = kd.x / kMag;
              forwardZ = kd.z / kMag;
            } else {
              forwardX = 0;
              forwardZ = 1;
            }
          } else {
            forwardX = Math.sin(bike.rotation.y) * dir;
            forwardZ = Math.cos(bike.rotation.y) * dir;
          }

          match.ball.velocity.x = forwardX * kickForce;
          match.ball.velocity.z = forwardZ * kickForce;
          match.ball.velocity.y = 3;

          match.ball.lastTouchBy = player.id;

          const pushOut = 1.2;
          match.ball.position.x += forwardX * pushOut;
          match.ball.position.z += forwardZ * pushOut;
        }
      }

      const ball = match.ball;
      const bdx = bike.position.x - ball.position.x;
      const bdz = bike.position.z - ball.position.z;
      const bdist = Math.sqrt(bdx * bdx + bdz * bdz);
      const minDist = 1.2;

      if (bdist < minDist && bdist > 0) {
        const overlap = minDist - bdist;
        const pushX = bdx / bdist * overlap * 0.5;
        const pushZ = bdz / bdist * overlap * 0.5;

        ball.position.x -= pushX;
        ball.position.z -= pushZ;

        const hitForce = Math.min(40, currentSpeed * 0.8 + 5);
        ball.velocity.x -= bdx / bdist * hitForce;
        ball.velocity.z -= bdz / bdist * hitForce;
        ball.velocity.y = Math.abs(bike.velocity.y) * 0.5 + 2;

        bike.position.x += pushX * 0.3;
        bike.position.z += pushZ * 0.3;

        ball.lastTouchBy = player.id;
      }
    });
  }

  private simulateAI(match: LocalMatch, dt: number) {
    match.players.forEach((player) => {
      if (!player.isAI) return;
      const inputs = this.getAIInput(player, match, match.teamMode[player.team]);
      match.lastInputs.set(player.id, inputs);
    });
  }

  private getAIInput(player: PlayerState, match: LocalMatch, teamMode: TeamMode = 'normal'): PlayerInput {
    const ball = match.ball;
    const myPos = player.bike.position;
    const isBlue = player.team === Team.Blue;

    const target = this.getAITarget(player, match, teamMode);
    const distToTarget = this.distance(myPos, target);

    const playerIndex = this.getPlayerIndex(player, match);
    const isGoalkeeper = playerIndex === 0;

    let steer = 0;
    let throttle = 0;
    let sprint = false;
    let jump = false;
    let kick = false;

    if (isGoalkeeper) {
      const goalX = isBlue ? -FIELD.LENGTH / 2 + 3 : FIELD.LENGTH / 2 - 3;
      const targetZ = Math.max(-FIELD.GOAL_WIDTH / 2 + 1, Math.min(FIELD.GOAL_WIDTH / 2 - 1, ball.position.z));

      const diffZ = targetZ - myPos.z;
      steer = Math.max(-1, Math.min(1, diffZ * 0.1));
      throttle = Math.abs(myPos.x - goalX) > 1 ? Math.sign(goalX - myPos.x) * 0.5 : 0;

      const distToBall = this.distance(myPos, ball.position);
      if (distToBall < 5 && Math.abs(ball.position.x - goalX) < 15) {
        throttle = Math.sign(ball.position.x - myPos.x) * 0.8;
        sprint = distToBall > 3;
      }
    } else {
      const angleToTarget = Math.atan2(target.z - myPos.z, target.x - myPos.x);
      let facingAngle = player.bike.rotation.y;
      if (isBlue) facingAngle = -facingAngle;

      let angleDiff = angleToTarget - facingAngle;
      while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
      while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;

      steer = Math.max(-1, Math.min(1, angleDiff * 2));

      if (teamMode === 'attack') {
        throttle = 1;
        sprint = true;
      } else if (teamMode === 'defence') {
        const ownGoalX = isBlue ? -FIELD.LENGTH / 2 : FIELD.LENGTH / 2;
        const distToOwnGoal = this.distance(myPos, { x: ownGoalX, y: 0, z: 0 });
        throttle = 0.7;
        sprint = distToOwnGoal < 30 && distToTarget < 10;
      } else {
        throttle = 0.8;
        sprint = distToTarget > 8 && Math.abs(angleDiff) < 0.5;
      }

      if (distToTarget < 2.5) {
        const goalPos = { x: isBlue ? FIELD.LENGTH / 2 - 2 : -FIELD.LENGTH / 2 + 2, y: 0, z: 0 };
        const angleToGoal = Math.atan2(goalPos.z - myPos.z, goalPos.x - myPos.x);
        const facingGoal = Math.abs(angleToGoal - facingAngle) < 0.5;

        if (teamMode === 'defence') {
          const ownGoalX = isBlue ? -FIELD.LENGTH / 2 : FIELD.LENGTH / 2;
          if (facingGoal) {
            kick = true;
            throttle = 1;
          } else {
            kick = true;
          }
        } else {
          if (facingGoal) {
            throttle = 1;
            sprint = true;
            kick = true;
          } else if (Math.random() < 0.3) {
            kick = true;
          }
        }
      }

      if (teamMode === 'attack') {
        const ownGoalX = isBlue ? -FIELD.LENGTH / 2 : FIELD.LENGTH / 2;
        const distToOwnGoal = this.distance(myPos, { x: ownGoalX, y: 0, z: 0 });
        if (distToOwnGoal < 15 && distToTarget > 8) {
          throttle = 1;
          sprint = true;
        }
      }

      if (teamMode === 'defence' && playerIndex >= 1 && playerIndex <= 3) {
        const ownGoalX = isBlue ? -FIELD.LENGTH / 2 : FIELD.LENGTH / 2;
        const distToOwnGoal = this.distance(myPos, { x: ownGoalX, y: 0, z: 0 });
        const distBallToOwnGoal = this.distance(ball.position, { x: ownGoalX, y: 0, z: 0 });
        if (distBallToOwnGoal < 40 && distToOwnGoal > 25) {
          throttle = 1;
          sprint = true;
        }
      }
    }

    if (Math.random() < 0.005) {
      jump = true;
    }

    return {
      steer,
      throttle,
      jump,
      sprint,
      kick,
      camera: { yaw: 0, pitch: 0 },
      sequence: Date.now(),
    };
  }

  private getAITarget(player: PlayerState, match: LocalMatch, teamMode: TeamMode): { x: number; y: number; z: number } {
    const ball = match.ball;
    const myPos = player.bike.position;
    const isBlue = player.team === Team.Blue;
    const playerIndex = this.getPlayerIndex(player, match);

    if (teamMode === 'attack') {
      const oppGoalX = isBlue ? FIELD.LENGTH / 2 - 5 : -FIELD.LENGTH / 2 + 5;
      if (playerIndex >= 4) {
        return {
          x: Math.max(-FIELD.LENGTH / 2 + 2, Math.min(FIELD.LENGTH / 2 - 2, ball.position.x * 0.5 + oppGoalX * 0.5)),
          y: 0,
          z: ball.position.z,
        };
      } else if (playerIndex <= 3) {
        const pushX = isBlue ? ball.position.x + 5 : ball.position.x - 5;
        return {
          x: Math.max(-FIELD.LENGTH / 2 + 5, Math.min(FIELD.LENGTH / 2 - 5, pushX)),
          y: 0,
          z: ball.position.z * 0.8,
        };
      }
    }

    if (teamMode === 'defence') {
      if (playerIndex <= 3) {
        const ownGoalX = isBlue ? -FIELD.LENGTH / 2 + 8 : FIELD.LENGTH / 2 - 8;
        const midX = (ball.position.x + ownGoalX) / 2;
        return {
          x: Math.max(-FIELD.LENGTH / 2 + 3, Math.min(FIELD.LENGTH / 2 - 3, midX)),
          y: 0,
          z: ball.position.z * 0.6,
        };
      } else {
        const ownGoalX = isBlue ? -FIELD.LENGTH / 2 : FIELD.LENGTH / 2;
        const backX = ball.position.x * 0.3 + ownGoalX * 0.7;
        return {
          x: Math.max(-FIELD.LENGTH / 2 + 3, Math.min(FIELD.LENGTH / 2 - 3, backX)),
          y: 0,
          z: ball.position.z * 0.7,
        };
      }
    }

    if (playerIndex <= 1) {
      const goalX = isBlue ? -FIELD.LENGTH / 2 + 5 : FIELD.LENGTH / 2 - 5;
      const targetX = (ball.position.x + goalX) / 2;
      const targetZ = ball.position.z * 0.5;
      return {
        x: Math.max(-FIELD.LENGTH / 2 + 5, Math.min(FIELD.LENGTH / 2 - 5, targetX)),
        y: 0,
        z: Math.max(-FIELD.WIDTH / 2 + 3, Math.min(FIELD.WIDTH / 2 - 3, targetZ)),
      };
    } else if (playerIndex <= 3) {
      const offset = isBlue ? -3 : 3;
      return {
        x: Math.max(-FIELD.LENGTH / 2 + 2, Math.min(FIELD.LENGTH / 2 - 2, ball.position.x + offset)),
        y: 0,
        z: ball.position.z,
      };
    } else {
      const goalX = isBlue ? FIELD.LENGTH / 2 - 5 : -FIELD.LENGTH / 2 + 5;
      return {
        x: Math.max(-FIELD.LENGTH / 2 + 2, Math.min(FIELD.LENGTH / 2 - 2, ball.position.x * 0.7 + goalX * 0.3)),
        y: 0,
        z: ball.position.z,
      };
    }
  }

  private getPlayerIndex(player: PlayerState, match: LocalMatch): number {
    let idx = 0;
    for (const [, p] of match.players) {
      if (p.team === player.team) {
        if (p.id === player.id) return idx;
        idx++;
      }
    }
    return 0;
  }

  private distance(a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }): number {
    return Math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2 + (a.z - b.z) ** 2);
  }

  private getFormationPosition(team: Team, index: number): { x: number; y: number; z: number } {
    const isBlue = team === Team.Blue;
    const direction = isBlue ? 1 : -1;
    const fieldLengthHalf = FIELD.LENGTH / 2 - 5;

    const positions: [number, number][] = [
      [fieldLengthHalf * direction * -0.95, 0],
      [fieldLengthHalf * direction * -0.6, -12],
      [fieldLengthHalf * direction * -0.6, 12],
      [fieldLengthHalf * direction * -0.2, -8],
      [fieldLengthHalf * direction * -0.2, 8],
      [fieldLengthHalf * direction * 0.3, 0],
    ];

    const pos = positions[index] || positions[5];
    return { x: pos[0], y: 0.5, z: pos[1] };
  }

  private resetPositions(match: LocalMatch) {
    let blueIdx = 0;
    let redIdx = 0;

    match.players.forEach((player) => {
      if (player.team === Team.Blue) {
        const pos = this.getFormationPosition(Team.Blue, blueIdx);
        player.bike.position = { ...pos };
        player.bike.rotation = { x: 0, y: 0, z: 0 };
        player.bike.velocity = { x: 0, y: 0, z: 0 };
        player.bike.angularVelocity = { x: 0, y: 0, z: 0 };
        player.bike.boost = BIKE.BOOST_MAX;
        blueIdx++;
      } else {
        const pos = this.getFormationPosition(Team.Red, redIdx);
        player.bike.position = { ...pos };
        player.bike.rotation = { x: 0, y: Math.PI, z: 0 };
        player.bike.velocity = { x: 0, y: 0, z: 0 };
        player.bike.angularVelocity = { x: 0, y: 0, z: 0 };
        player.bike.boost = BIKE.BOOST_MAX;
        redIdx++;
      }
    });

    match.ball = {
      position: { x: 0, y: BALL.RADIUS, z: 0 },
      velocity: { x: 0, y: 0, z: 0 },
      lastTouchBy: null,
    };
  }

  private broadcastState(match: LocalMatch) {
    const playersObj: Record<string, PlayerState> = {};
    match.players.forEach((p, id) => {
      playersObj[id] = p;
    });

    this.callbacks.onStateUpdate({
      id: match.id,
      state: match.state,
      players: playersObj,
      ball: match.ball,
      blueScore: match.blueScore,
      redScore: match.redScore,
      elapsedSeconds: match.elapsedSeconds,
      kickoffTimer: match.kickoffTimer,
    });
  }
}
